"""Task A evidence checks; no containers, Maven, models or parallel workers."""
import copy
import hashlib
import json
from pathlib import Path
import pytest
from tools import review_phase5_2_2_a as audit

BASE=Path(__file__).resolve().parents[1]


@pytest.mark.parametrize('value',['@param autoUsage whether to print an automatically generated usage statement',
                                  'The default style as generated by the default Builder.'])
def test_output_generation_is_not_generated_source(value):
    result=audit.dispositions(dict(generated=[dict(line=12,text=value)],vendor=[]))
    assert len(result)==1 and result[0]['line']==12


@pytest.mark.parametrize('kind,text',[('generated','DO NOT EDIT: generated file'),('vendor','Copied from another project')])
def test_unknown_signals_never_auto_approved(kind,text):
    signals=dict(generated=[],vendor=[]);signals[kind]=[dict(line=1,text=text)]
    with pytest.raises(ValueError,match='Unresolved'):audit.dispositions(signals)


def test_bounded_local_reads(tmp_path):
    p=tmp_path/'large';p.write_bytes(b'x'*10)
    with pytest.raises(ValueError):audit.bounded(p,9)
    assert audit.bounded(p,10)==b'x'*10


def test_blob_size_checked_before_content(monkeypatch):
    calls=[]
    def fake(path,*args):
        calls.append(args);return str(audit.MAX_FILE+1).encode()
    monkeypatch.setattr(audit,'git',fake)
    with pytest.raises(ValueError):audit.read_blob('unused','a'*40)
    assert calls==[('cat-file','-s','a'*40)]


def test_license_mismatch_and_notice_not_permission():
    with pytest.raises(ValueError):audit.license_evidence('pallets/click','LICENSE.txt','a'*40,b'unknown terms')
    record=audit.license_evidence('apache/commons-cli','NOTICE.txt','a'*40,b'synthetic attribution')
    assert record['role']=='ATTRIBUTION_NOTICE' and record['detected_license'] is None
    assert record['ownership_or_project_permission_certified'] is False


def test_cached_analyzer_license_digest_required():
    published=dict(plugins=[dict(filename='fixture',sha256='a'*64)])
    row=dict(plugin='fixture',private_text='changed',sha256='b'*64,path='LICENSE.txt')
    with pytest.raises(ValueError):audit.embedded_analyzer_rights([row],published)


def test_no_analyzer_permission_inferred():
    text='SONAR Source-Available License v1.0\nNon-competitive Purpose excludes artificial intelligence technology'
    cached=[dict(plugin=f'fixture-{i}',private_text=text,sha256=hashlib.sha256(text.encode()).hexdigest(),path='LICENSE.txt') for i in range(3)]
    published=dict(plugins=[dict(filename=v['plugin'],sha256='a'*64) for v in cached])
    result=audit.embedded_analyzer_rights(cached,published)
    assert all(v['permission_for_planned_ai_use']=='NOT_ESTABLISHED' for v in result)
    assert all(v['independent_reextraction_this_task'] is False for v in result)


def test_cached_analyzer_duplicates_rejected():
    text='SONAR Source-Available License v1.0\nNon-competitive Purpose artificial intelligence technology'
    row=dict(plugin='fixture',private_text=text,sha256=hashlib.sha256(text.encode()).hexdigest(),path='LICENSE.txt')
    with pytest.raises(ValueError):audit.embedded_analyzer_rights([row,row,row],dict(plugins=[dict(filename='fixture',sha256='a'*64)]))


def test_published_review_covers_exact_frozen_grid():
    checklist=json.loads((BASE/'examples/phase5_2_2_a/content_rights_checklist.json').read_text())
    frozen=json.loads((BASE/'examples/phase5_2_1/readiness_manifest.json').read_text())
    identity=lambda s:(s['repository_id'],s['commit_sha'],s['tree_sha'],s['cutoff_utc'],s['native_project_key_plan'])
    assert {identity(s) for s in checklist['states']}=={identity(s) for s in frozen['planned_source_states']}
    assert len(checklist['states'])==18
    assert all(s['legal_acceptance'] is False for s in checklist['states'])
    assert all(s['operational_admission_status']=='QUARANTINE_UNCHANGED' for s in checklist['states'])
    assert checklist['task_b_authorized'] is False
    assert all(v['status']=='NOT_APPROVED' for v in checklist['human_approvals'])
    assert sum(v['production_files'] for v in checklist['states'])==342
    assert sum(v['tracked_files'] for v in checklist['states'])==2046
